insert into public.game_reviews (game_id, id, sort_order, author, avatar_src, time_label, rating, text, likes, liked) values
  ('mundial-fifa-2026', 'jordan-smith', 1, 'Jordan Smith', '/assets/games/detail/review-jordan.webp', 'Hace 12 horas', 5, '¡El mejor juego para móvil que he jugado este año! Los desarrolladores claramente le dedicaron mucho esfuerzo a cada aspecto del juego. ¡Lo recomiendo muchísimo!', 5, false),
  ('mundial-fifa-2026', 'taylor-kim', 2, 'Taylor Kim', '/assets/games/detail/review-taylor.webp', 'Hace 2 días', 3, 'Quería que me gustara este juego, pero se bloquea con demasiada frecuencia en mi dispositivo.', 995, true),
